s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:24:"https://fr.wordpress.org";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:5:"width";a:1:{i:0;a:5:{s:4:"data";s:2:"32";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:6:"height";a:1:{i:0;a:5:{s:4:"data";s:2:"32";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}}s:4:"item";a:10:{i:0;a:6:{s:4:"data";s:73:"\n		\n		\n					\n		\n		\n		\n				\n		\n\n					\n										\n					\n					\n			\n		\n		\n			";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:5:{s:0:"";a:7:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:55:"Questionnaire annuel sur votre utilisation de WordPress";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:97:"https://fr.wordpress.org/2023/10/10/questionnaire-annuel-sur-votre-utilisation-de-wordpress-2023/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"comments";a:1:{i:0;a:5:{s:4:"data";s:105:"https://fr.wordpress.org/2023/10/10/questionnaire-annuel-sur-votre-utilisation-de-wordpress-2023/#respond";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Tue, 10 Oct 2023 13:03:00 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:1:{i:0;a:5:{s:4:"data";s:23:"Questionnaires/sondages";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:32:"https://fr.wordpress.org/?p=2852";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:392:"Comme chaque année, l’équipe «&#160;Community&#160;» soumet un petit questionnaire à l&#8217;ensemble de la communauté WordPress. En effet, votre voix compte&#160;! Si vous êtes un utilisateur ou une utilisatrice de WordPress, si vous concevez des sites avec ce CMS, si vous développez des thèmes ou des extensions, si vous contribuez à la traduction, si vous participez [&#8230;]";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:11:"Jenny Dupuy";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:6355:"\n<p>Comme chaque année, l’équipe «&nbsp;<a href="https://make.wordpress.org/community/" data-type="link" data-id="https://make.wordpress.org/community/">Community</a>&nbsp;» soumet un petit questionnaire à l&rsquo;ensemble de la communauté WordPress.</p>\n\n\n\n<p><strong>En effet, votre voix compte&nbsp;!</strong> Si vous êtes un utilisateur ou une utilisatrice de WordPress, si vous concevez des sites avec ce CMS, si vous développez des thèmes ou des extensions, si vous contribuez à la traduction, si vous participez au développement du cœur de WordPress ou à sa communauté, alors vous êtes concerné·e·s par ce questionnaire.</p>\n\n\n\n<p>Les principales conclusions et tendances qui émergent de ce questionnaire sont communiquées dans la conférence annuelle&nbsp;<em><strong>State of the Word</strong></em>, puis partagées dans les blogs publics du projet et auront une influence sur la direction stratégique du projet dans les années à venir.</p>\n\n\n\n<p>En d‘autres termes, cette enquête aidera celles et ceux qui construisent WordPress à mieux comprendre comment le logiciel est utilisé et par qui. L‘enquête permet également aux responsables du projet open source WordPress d‘en savoir plus sur les expériences des personnes qui contribuent au projet.</p>\n\n\n\n<div class="wp-block-buttons is-content-justification-center is-layout-flex wp-container-1 wp-block-buttons-is-layout-flex">\n<div class="wp-block-button"><a class="wp-block-button__link wp-element-button" href="https://survey.alchemer.com/s3/7439442/2023-WordPress-Annual-Survey" target="_blank" rel="noreferrer noopener">C’est parti ! Je remplis le questionnaire 2023</a></div>\n</div>\n\n\n\n<p>Le questionnaire est disponible en différentes langues, dont le français, merci aux contributeurs polyglotes pour leurs traductions.</p>\n\n\n\n<p>L’enquête est ouverte pour cinq semaines et les résultats seront publiés début décembre sur le <a rel="noreferrer noopener" href="https://wordpress.org/news/" data-type="link" data-id="https://wordpress.org/news/" target="_blank">blog News</a>.</p>\n\n\n\n<p>Cette année, comme l’année dernière, l’enquête a fait l’objet de quelques améliorations au niveau du déroulement et de l’ensemble des questions. Une nouvelle plateforme est également à l’essai, offrant une interface actualisée, un support multilingue amélioré, des outils d’analyse et de visualisation des résultats élargis, et bien plus encore. La nouvelle plateforme intègre également des contrôles d’accessibilité et de confidentialité, ce qui garantit que l’enquête répond aux divers besoins de la communauté WordPress.</p>\n\n\n\n<h2 class="wp-block-heading">Passez le mot</h2>\n\n\n\n<p>Aidez-nous à faire connaître l’enquête en la partageant avec votre réseau, via Slack, ou sur vos comptes de médias sociaux. Plus il y aura de personnes qui répondront à l’enquête et qui partageront leur expérience avec WordPress, plus le projet en bénéficiera.</p>\n\n\n\n<h2 class="wp-block-heading">Sécurité et vie privée</h2>\n\n\n\n<p>La sécurité et la confidentialité des données sont primordiales pour le projet et la communauté WordPress. Dans cette optique, toutes les données seront anonymisées : aucune adresse e-mail ou adresse IP ne sera associée aux résultats publiés. Pour en savoir plus sur les pratiques de WordPress.org en matière de confidentialité, consultez la <a href="https://wordpress.org/about/privacy/" data-type="link" data-id="https://wordpress.org/about/privacy/">politique de confidentialité (en anglais)</a>.</p>\n\n\n\n<h2 class="wp-block-heading">Merci</h2>\n\n\n\n<p>Nous remercions les contributeurs WordPress suivants pour leur aide dans le projet d’enquête annuelle, y compris la création des questions, la stratégie, l’élaboration de l&rsquo;enquête et la traduction :</p>\n\n\n\n<p><a href="https://profiles.wordpress.org/adamsilverstein/">adamsilverstein</a>, <a href="https://profiles.wordpress.org/audrasjb/">audrasjb</a>, <a href="https://profiles.wordpress.org/alvarogois/">alvarogóis</a>, <a href="https://profiles.wordpress.org/atachibana/">atachibana</a>, <a href="https://profiles.wordpress.org/bjmcsherry/">bjmcsherry</a>, <a href="https://profiles.wordpress.org/chanthaboune/">chanthaboune</a>, <a href="https://profiles.wordpress.org/dansoschin/">dansoschi</a>, <a href="https://profiles.wordpress.org/eidolonnight/">eidolonnight</a>, <a href="https://profiles.wordpress.org/fierevere/">fierevere</a>, <a href="https://profiles.wordpress.org/fxbenard/">fxbénard</a>, <a href="https://profiles.wordpress.org/hassantafreshi/">hassantafreshi</a>, <a href="https://profiles.wordpress.org/juliagasparyan/">juliagasparyan</a>, <a href="https://profiles.wordpress.org/kittmedia/">kittmedia</a>, <a href="https://profiles.wordpress.org/manudavidos/">manudavidos</a>,<a href="https://profiles.wordpress.org/nao/">nao</a>, <a href="https://profiles.wordpress.org/nilovelez/">nilovelez</a>, <a href="https://profiles.wordpress.org/rmartinezduque/">rmartinezduque</a> et <a href="https://profiles.wordpress.org/tobifjellner/">tobifjellner</a>.</p>\n\n\n\n<p>Merci à&nbsp;<a href="https://www.hostinger.com/">Hostinger</a>,&nbsp;<a href="https://cloud.jetpack.com/">Jetpack</a>, and&nbsp;<a href="http://wordpress.com/">WordPress.com</a>, pour avoir contribué à la promotion de l’enquête auprès de leurs clients respectifs.</p>\n\n\n\n<div class="wp-block-buttons is-content-justification-center is-layout-flex wp-container-2 wp-block-buttons-is-layout-flex">\n<div class="wp-block-button"><a class="wp-block-button__link wp-element-button" href="https://survey.alchemer.com/s3/7439442/2023-WordPress-Annual-Survey" target="_blank" rel="noreferrer noopener">C’est parti ! Je remplis le questionnaire 2023</a></div>\n</div>\n\n\n\n<p>L’enquête sera close le <a href="https://www.timeanddate.com/worldclock/fixedtime.html?iso=20231031T1600"><time datetime="2023-10-31T16:00:00-04:00">mardi 31 octobre 2023 à 17:00 UTC+1</time></a>.</p>\n\n\n\n<p>Merci à <a href="https://profiles.wordpress.org/audrasjb" data-type="link" data-id="https://profiles.wordpress.org/audrasjb">JB Audras</a> et <a href="https://profiles.wordpress.org/fxbenard/" data-type="link" data-id="https://profiles.wordpress.org/fxbenard/">FX Bénard</a> pour leur relecture de cet article.</p>\n";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:36:"http://wellformedweb.org/CommentAPI/";a:1:{s:10:"commentRss";a:1:{i:0;a:5:{s:4:"data";s:102:"https://fr.wordpress.org/2023/10/10/questionnaire-annuel-sur-votre-utilisation-de-wordpress-2023/feed/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:38:"http://purl.org/rss/1.0/modules/slash/";a:1:{s:8:"comments";a:1:{i:0;a:5:{s:4:"data";s:1:"0";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}i:1;a:6:{s:4:"data";s:73:"\n		\n		\n					\n		\n		\n		\n				\n		\n\n					\n										\n					\n					\n			\n		\n		\n			";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:5:{s:0:"";a:7:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:28:"WordPress 6.3 « Lionel »";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:57:"https://fr.wordpress.org/2023/08/08/wordpress-6-3-lionel/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"comments";a:1:{i:0;a:5:{s:4:"data";s:65:"https://fr.wordpress.org/2023/08/08/wordpress-6-3-lionel/#respond";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Tue, 08 Aug 2023 22:03:41 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:1:{i:0;a:5:{s:4:"data";s:31:"Nouvelles versions de WordPress";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:32:"https://fr.wordpress.org/?p=2817";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:424:"Nous vous présentons WordPress 6.3 «&#160;Lionel&#160;», nommé après la jazzman américain&#160;Lionel Hampton. Il fut un vibraphoniste, pianiste et percussionniste de jazz prolifique et obtint sa notoriété en jouant avec des grands du jazz comme&#160;Charles Mingus&#160;ou&#160;Quincy Jones, et en tant que leader du Lionel Hampton Orchestra. Ses travaux ont été récompensés par un Grammy, une étoile [&#8230;]";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:9:"Jb Audras";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:66495:"\n<figure class="wp-block-image size-large"><a href="https://fr.wordpress.org/files/2023/08/6.3-Release-Edition-Main-Image.png"><img fetchpriority="high" decoding="async" width="1024" height="683" src="https://fr.wordpress.org/files/2023/08/6.3-Release-Edition-Main-Image-1024x683.png" alt="" class="wp-image-2834" srcset="https://fr.wordpress.org/files/2023/08/6.3-Release-Edition-Main-Image-1024x683.png 1024w, https://fr.wordpress.org/files/2023/08/6.3-Release-Edition-Main-Image-300x200.png 300w, https://fr.wordpress.org/files/2023/08/6.3-Release-Edition-Main-Image-768x512.png 768w, https://fr.wordpress.org/files/2023/08/6.3-Release-Edition-Main-Image-1536x1024.png 1536w, https://fr.wordpress.org/files/2023/08/6.3-Release-Edition-Main-Image-2048x1365.png 2048w" sizes="(max-width: 1024px) 100vw, 1024px" /></a></figure>\n\n\n\n<p>Nous vous présentons WordPress 6.3 «&nbsp;Lionel&nbsp;», nommé après la jazzman américain&nbsp;<a href="https://en.wikipedia.org/wiki/Lionel_Hampton">Lionel Hampton</a>. Il fut un vibraphoniste, pianiste et percussionniste de jazz prolifique et obtint sa notoriété en jouant avec des grands du jazz comme&nbsp;<a href="https://en.wikipedia.org/wiki/Charles_Mingus">Charles Mingus</a>&nbsp;ou&nbsp;<a href="https://en.wikipedia.org/wiki/Quincy_Jones">Quincy Jones</a>, et en tant que <bdo lang="en" dir="ltr">leader</bdo> du <em><bdo lang="en" dir="ltr">Lionel Hampton Orchestra</bdo></em>. Ses travaux ont été récompensés par un <em><bdo lang="en" dir="ltr">Grammy</bdo></em>, une étoile sur le <bdo lang="en" dir="ltr"><em>Hollywood Walk of Fame</em></bdo>, et la <em><bdo lang="en" dir="ltr">National Medal of Arts</bdo></em> américaine.</p>\n\n\n\n<p>Avec WordPress 6.3, vous pourrez créer de beaux sites web plus efficacement que jamais. Que vous souhaitiez créer un site complet sans coder ou que vous cherchiez à personnaliser chaque détail avec votre propre code, WordPress 6.3 a quelque chose à vous offrir.</p>\n\n\n\n<blockquote class="wp-block-quote">\n<p>«&nbsp;Lionel&nbsp;» marque un chapitre majeur dans l’évolution de WordPress. C’est le point culminant d’années de travail par des centaines de contributeurs et contributrices pour faire évoluer l’expérience d’édition de votre site WordPress vers davantage de cohérence, à l’aide des blocs. Mais notre quête de vouloir démocratiser la publication sur le web n’est pas finie pour autant&nbsp;!</p>\n<cite><strong>Matías Ventura, Directeur de la version 6.3</strong></cite></blockquote>\n\n\n\n<div class="wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex">\n<div class="wp-block-button has-custom-font-size is-style-fill has-medium-font-size"><a class="wp-block-button__link has-vivid-cyan-blue-background-color has-background wp-element-button" href="https://fr.wordpress.org/download/" style="border-radius:0px;padding-top:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20)">Télécharger WordPress 6.3 «&nbsp;Lionel&nbsp;»</a></div>\n</div>\n\n\n\n<h2 class="wp-block-heading">Bienvenue sur WordPress 6.3</h2>\n\n\n\n<h3 class="wp-block-heading">Tout faire dans l’Éditeur de site</h3>\n\n\n\n<figure class="wp-block-image"><img decoding="async" src="https://lh3.googleusercontent.com/ECKi32pUTHxKbtb7u2yXNt9VgtbETFiOhEXsmkTg-kwtTWz6Hors0QmayvKH57LONBPvrztSU29SIOYyUeMQJFfbZ3sHeml1bPGVyqHtMtgjCFv8yVkUhkxBYZhf2ZiKNW_GgbcT_SZ9tAkQjyxe1_c" alt="" /></figure>\n\n\n\n<p>WordPress 6.3 rassemble pour la première fois votre contenu, vos modèles et vos compositions dans l’éditeur de site. Ajoutez des pages, parcourez les variations de styles, créez des compositions synchronisées et bénéficiez d’un contrôle précis sur vos menus de navigation. Vous ne perdrez plus de temps à passer d’une zone de site à l’autre, et vous pourrez vous concentrer sur ce qui compte le plus. De la création à la publication, en un seul endroit.</p>\n\n\n\n<h3 class="wp-block-heading">Prévisualiser les thèmes basés sur des blocs</h3>\n\n\n\n<figure class="wp-block-image"><img decoding="async" src="https://lh6.googleusercontent.com/tqCEcJeH36DRnaTb-clxC54AoEYEy-GVea8AGiDU8_F5Z98x_DdllvuYVLNacitS3uS4Oy3fEzs3u_ESELe2K5KF2tX_ikroxHe9sanJ5pYVhVnoAnG_mtcrRmUFXTx5ug1Bl2YwwPvnBRZj-fHrym8" alt="" /></figure>\n\n\n\n<p>Expérimentez les thèmes basés sur des blocs avant de les choisir et prévisualisez l’éditeur de site, avec des options à personnaliser directement avant d’activer un nouveau thème.</p>\n\n\n\n<h3 class="wp-block-heading">Créez et synchronisez vos compositions</h3>\n\n\n\n<figure class="wp-block-image"><img decoding="async" src="https://lh3.googleusercontent.com/rdzZc0SGnFQ188wmNqBhUMpq3fStbcUlZzSM_DwWdNgM-0fALWPWEzMfjCuOsLqpw6uNcI1i1AAiiDiLnHWSSVO3TtliLD2QNkhGuQ1qpaogZ3RrNHAtSG_85ai4zqZk2fF2ae7AEnliDWxRpf1ocDA" alt="" /></figure>\n\n\n\n<p>Disposez les blocs avec un nombre infini de variantes et enregistrez-les en tant que compositions pour les utiliser sur l’ensemble de votre site. Vous pouvez même indiquer si vous souhaitez synchroniser vos compositions (précédemment appelés «&nbsp;blocs réutilisables&nbsp;») afin qu’une modification s’applique à toutes les parties de votre site. Vous pouvez également garder la possibilité de personnaliser chaque instance.</p>\n\n\n\n<h2 class="wp-block-heading">Travaillez plus rapidement avec la palette de commandes</h2>\n\n\n\n<figure class="wp-block-image"><img decoding="async" src="https://lh3.googleusercontent.com/IASpGRTrnrOzs4pvDPgEKqMQwuXNJRBqbDRHXlzLmvcsKvlIv_D2Iax_IzZ0eP15i2Xq8YDo288lB9WJGjbk_aceRQgDZGBMgMOzcPxG3L4xo92aGqlb9nbqdup6Qwt3vISHCz4wjylYAgGJwLdwbpw" alt="" /></figure>\n\n\n\n<p>Basculez sur un modèle spécifique ou ouvrez les préférences de votre éditeur à l’aide d’un nouvel outil qui vous aide à naviguer rapidement dans les fonctionnalités étendues. Grâce à de simples raccourcis clavier (⌘+k sur Mac ou CTRL+k sur Windows), en cliquant sur l’icône de recherche de la colonne latérale de l’éditeur de site, ou en cliquant sur la barre de titre, vous pouvez vous rendre où vous voulez et faire ce que vous voulez en quelques secondes.</p>\n\n\n\n<h3 class="wp-block-heading"><br>Affinez vos designs avec de nouveaux outils</h3>\n\n\n\n<figure class="wp-block-image"><img decoding="async" src="https://lh3.googleusercontent.com/C44Qs_vplLP0rB_ZUERqipYWXuFzdnvu8nxmz6EpUW3vyXnWbfbfwbvYvzfaQyu24F7nxRjKossThzuXqJNKnUyQBjShITCVwhhKYUhwa14UyL2JwVn7D71zV0yyZVYm7ASyRO1whyHfOT4zgqFpizQ" alt="" /></figure>\n\n\n\n<p>Les nouveaux réglages de design offrent une plus grande polyvalence pour affiner vos mises en pages, à commencer par la possibilité de personnaliser les styles de vos légendes à partir de l’interface des styles, sans codage. Vous pouvez gérer vos filtres duotone dans les réglages de style et choisir parmi les options fournies par votre thème, mais aussi les désactiver complètement. Le bloc Bannière bénéficie de réglages supplémentaires pour la couleur du texte, les réglages de mise en page et de bordure, ce qui rend ce bloc puissant encore plus pratique.</p>\n\n\n\n<h3 class="wp-block-heading">Suivez vos modifications de design avec les révisions de styles</h3>\n\n\n\n<figure class="wp-block-image"><img decoding="async" src="https://lh3.googleusercontent.com/1al2dPJV09Plk8suFtnJI81L754Jl6QCq30_UTbGJ9ln0zJ3ig8BEIVU_BX8zRvZst8KUFxr6ny7Ohv3lNEgp4cZruSdrcuZjT8efmIifW1G3-lP4H4J1qWhby9RfCUSBaMmarBqwM3Kp22m-38hesc" alt="" /></figure>\n\n\n\n<p>Vous pouvez désormais voir à quoi ressemblait votre site à un moment précis. Visualisez ces révisions sur une chronologie et accédez à une option de restauration des styles antérieurs en un seul clic.</p>\n\n\n\n<h3 class="wp-block-heading">Annotez vos publications avec le bloc «&nbsp;Notes de bas de page&nbsp;»</h3>\n\n\n\n<figure class="wp-block-image"><img decoding="async" src="https://lh4.googleusercontent.com/94NEMrm0MHPM8QtVzM1W61Pz452Jgp_xzDhHR-35QgOlkABny_gzjmTh-Z-ij8cAH8C_rp0ggLp2VB5AAOtCwJrTJ4Q6rUpehnL-tFxnTw75AaMVInZfChWg2VudW6yKUthshxnQLM3xmQmtmDnFexs" alt="" /></figure>\n\n\n\n<p>Les notes de bas de page ajoutent des annotations pratiques à votre contenu. Vous pouvez désormais ajouter et lier des notes de bas de page à n’importe quel mot d’un paragraphe.</p>\n\n\n\n<h3 class="wp-block-heading">Affichez ou masquez du contenu avec le bloc Détails</h3>\n\n\n\n<figure class="wp-block-image"><img decoding="async" src="https://lh5.googleusercontent.com/Ed5esxwS6U5Z3sBWkeV7ZuNau-izTZQqwxzz6F0ww9qx4XnyqKVT8JZTP0eahDDO73psW7gOxz3KghGyBOeuNW5L3LKw0MJAeISUhAtvqNyThT1Or8gybCIJGhHFyh6njVun5_KumEkMoR5cgXBK_-Q" alt="" /></figure>\n\n\n\n<p>Utilisez ce bloc pour éviter de divulgâcher une surprise, pour créer une section de foire aux questions interactive, ou pour masquer un long paragraphe derrière un titre.</p>\n\n\n\n<h3 class="wp-block-heading">Amélioration des performances</h3>\n\n\n\n<p>WordPress 6.3 contient plus de <a href="https://make.wordpress.org/core/2023/08/07/wordpress-6-3-performance-improvements/">170 mises à jour de performances (en anglais)</a>, comprenant la prise en charge des attributs&nbsp;<code>defer</code>&nbsp;et&nbsp;<code>async</code>&nbsp;pour l’API Scripts et&nbsp;<code>fetchpriority</code>&nbsp;pour les images. Avec les évolutions concernant la résolution des modèles de blocs, le chargement différé des images et le chargement des emojis, ces améliorations peuvent diminuer le temps de chargement de votre site web tel qu’il est perçu par les visiteurs.</p>\n\n\n\n<h3 class="wp-block-heading">L‘accessibilité reste une priorité</h3>\n\n\n\n<p>Avec plus de 50 améliorations de l’accessibilité sur l’ensemble de la plateforme, WordPress 6.3 est plus accessible que jamais. L’amélioration des libellés, l’optimisation de la navigation par onglets et par touches fléchées, la révision de la hiérarchie des titres et les nouveaux contrôles dans l’éditeur d’images de l’administrateur permettent aux personnes qui utilisent des technologies d’assistance d’administrer plus facilement leur site.</p>\n\n\n\n<h3 class="wp-block-heading">Autres améliorations</h3>\n\n\n\n<h4 class="wp-block-heading">Définir les proportions de taille des images</h4>\n\n\n\n<p>Spécifiez vos proportions et assurez l’intégrité de la conception, en particulier lorsque vous utilisez des images dans des compositions.</p>\n\n\n\n<h4 class="wp-block-heading">Construire son site sans distraction</h4>\n\n\n\n<p>La conception sans distraction est désormais disponible dans l’Éditeur de site.</p>\n\n\n\n<h4 class="wp-block-heading">Redécouvrez la barre d’outils supérieure</h4>\n\n\n\n<p>La barre d’outils supérieure remaniée propose des sélecteurs de parents pour les blocs imbriqués, des options pour la sélection de plusieurs blocs, ainsi qu’une nouvelle interface intégrée à la barre de titre avec de nouvelles fonctionnalités à l’esprit.</p>\n\n\n\n<h4 class="wp-block-heading">Améliorations de la vue de la liste</h4>\n\n\n\n<p>Faites un glisser-déposer vers un autre emplacement et supprimez les blocs de votre choix dans la vue en liste mise à jour en temps réel.</p>\n\n\n\n<h4 class="wp-block-heading">Construire des modèles grâce aux compositions</h4>\n\n\n\n<p>Créez des compositions uniques pour accélérer la création de modèles grâce à une nouvelle fenêtre modale permettant d’accéder à la sélection des compositions.</p>\n\n\n\n<h2 class="wp-block-heading">En savoir plus sur WordPress 6.3</h2>\n\n\n\n<p><a href="https://learn.wordpress.org/">Learn WordPress (en anglais)</a>&nbsp;est une ressource gratuite pour les utilisateurs/utilisatrices de WordPress, qu’ils/elles soient débutant·e·s ou expérimenté·e·s. Learn contient des vidéos pratiques sur l’utilisation de diverses fonctionnalités de WordPress, des&nbsp;<a href="https://learn.wordpress.org/online-workshops/">évènements interactifs (en anglais)</a>&nbsp;pour explorer des sujets en profondeur, et des plans de cours pour approfondir des domaines spécifiques de WordPress.</p>\n\n\n\n<p>Consultez notre&nbsp;<a href="https://fr.wordpress.org/2023/07/18/guide-des-changements-techniques-de-wordpress-6-3/">guide des changements techniques introduits par WordPress 6.3</a>. Il contient toutes les notes techniques que vous devez connaître si vous développez sur WordPress.</p>\n\n\n\n<p><a href="https://wordpress.org/support/wordpress-version/version-6-3/">Consultez les notes de version de WordPress 6.3 (en anglais)</a>&nbsp;pour obtenir plus d’informations sur les améliorations proposées et les anomalies corrigées, les informations d’installation, les notes et ressources à destination des développeuses et des développeurs, connaître les personnes ayant contribué à cette version et pour obtenir la liste des fichiers modifiés.</p>\n\n\n\n<h3 class="wp-block-heading">L’équipe de direction de WordPress 6.3</h3>\n\n\n\n<p>Voici l’équipe qui a coordonné le développement et la sortie cette nouvelle version de WordPress&nbsp;:</p>\n\n\n\n<ul>\n<li><strong>Direction générale&nbsp;:</strong>&nbsp;<a href="https://profiles.wordpress.org/matveb/">Matías Ventura</a></li>\n\n\n\n<li><strong>Coordination de la version&nbsp;:</strong>&nbsp;<a href="https://profiles.wordpress.org/francina/">Francesca Marano</a>,&nbsp;<a href="https://profiles.wordpress.org/priethor/">Héctor Prieto</a></li>\n\n\n\n<li><strong>Direction technique du cœur WP&nbsp;:</strong>&nbsp;<a href="https://profiles.wordpress.org/azaozz/">Andrew Ozz</a>,&nbsp;<a href="https://profiles.wordpress.org/mikeschroder/">Mike Schroder</a></li>\n\n\n\n<li><strong>Direction technique de l’éditeur&nbsp;:</strong>&nbsp;&nbsp;<a href="https://profiles.wordpress.org/isabel_brison/">Isabel Brison</a>,&nbsp;<a href="https://profiles.wordpress.org/ramonopoly/">Ramon Dodd</a></li>\n\n\n\n<li><strong>Gestion de projet côté Cœur WP&nbsp;:</strong>&nbsp;<a href="https://profiles.wordpress.org/audrasjb/">Jb Audras</a>,&nbsp;<a href="https://profiles.wordpress.org/chaion07/">Ahmed Kabir Chaion</a>,&nbsp;<a href="https://profiles.wordpress.org/mukesh27/">Mukesh Panchal</a>,&nbsp;<a href="https://profiles.wordpress.org/oglekler/">Olga Glecker</a></li>\n\n\n\n<li><strong>Gestion de projet côté Éditeur&nbsp;:</strong>&nbsp;<a href="https://profiles.wordpress.org/annezazu/">Anne McCarthy</a>,&nbsp;<a href="https://profiles.wordpress.org/bph/">Birgit Pauli-Haack</a>,&nbsp;<a href="https://profiles.wordpress.org/firoz2456/">Firoz Sabaliya</a>,&nbsp;<a href="https://profiles.wordpress.org/ndiego/">Nick Diego</a></li>\n\n\n\n<li><strong>Direction de la documentation&nbsp;:</strong>&nbsp;<a href="https://profiles.wordpress.org/femkreations/">Femy Praseeth</a>,&nbsp;<a href="https://profiles.wordpress.org/stevenlinx/">Steven Lin</a>,&nbsp;<a href="https://profiles.wordpress.org/leonnugraha/">Leonardus Nugraha</a>,&nbsp;<a href="https://profiles.wordpress.org/611shabnam/">Mushrit Shabnam</a></li>\n\n\n\n<li><strong>Direction marketing &amp; communication&nbsp;:</strong>&nbsp;<a href="https://profiles.wordpress.org/dansoschin/">Dan Soschin</a>,&nbsp;<a href="https://profiles.wordpress.org/jpantani/">Jonathan Pantani</a>,&nbsp;<a href="https://profiles.wordpress.org/meher/">Meher Bala</a></li>\n\n\n\n<li><strong>Direction des tests&nbsp;:</strong>&nbsp;<a href="https://profiles.wordpress.org/ironprogrammer/">Brian Alexander</a>,&nbsp;<a href="https://profiles.wordpress.org/webtechpooja/">Pooja Derashri</a>,&nbsp;<a href="https://profiles.wordpress.org/chrismalone617/">Chris Malone</a></li>\n\n\n\n<li><strong>Direction du design&nbsp;:</strong>&nbsp;<a href="https://profiles.wordpress.org/karmatosed/">Tammie Lister</a>,&nbsp;<a href="https://profiles.wordpress.org/richtabor/">Rich Tabor</a></li>\n\n\n\n<li><strong>Responsables des performances&nbsp;:</strong>&nbsp;<a href="https://profiles.wordpress.org/flixos90/">Felix Arntz</a>,&nbsp;<a href="https://profiles.wordpress.org/clarkeemily/">Emily Clarke</a></li>\n</ul>\n\n\n\n<h3 class="wp-block-heading">Merci aux contributeurs et contributrices</h3>\n\n\n\n<p>WordPress 6.3 n’aurait pas pu sortir sans la contribution passionnée de plus de 650 personnes provenant d’au moins 52 pays différents. Un remerciement tout spécial pour les 207 personnes qui ont contribué au c